import assert from "node:assert/strict";
import { test } from "node:test";

import { hasSessionToRedirect, isValidSessionToken } from "./auth.ts";

// Generated by the backend's create_token; the same string is asserted in its tests.
const VECTOR = "7.2.2593000.h4iwZlqGe1wYGglpni-75ZF6nkgb-yIC90TlA69JV7k";
const SECRET = "vector-secret";

test("accepts the token vector generated by the backend", () => {
  assert.equal(isValidSessionToken(VECTOR, SECRET, 1000), true);
});

test("is valid until the second before expiry", () => {
  assert.equal(isValidSessionToken(VECTOR, SECRET, 2_592_999), true);
});

test("rejects a tampered token", () => {
  assert.equal(isValidSessionToken(VECTOR.replace("7.2.", "8.2."), SECRET, 1000), false);
  assert.equal(isValidSessionToken(VECTOR.replace(".2.", ".3."), SECRET, 1000), false);
  assert.equal(isValidSessionToken(VECTOR.replace("2593000", "2593001"), SECRET, 1000), false);
  assert.equal(isValidSessionToken(VECTOR, "other-secret", 1000), false);
});

test("rejects an expired token", () => {
  assert.equal(isValidSessionToken(VECTOR, SECRET, 2_593_000), false);
  assert.equal(isValidSessionToken(VECTOR, SECRET, 3_000_000), false);
});

for (const token of [undefined, "", "garbage", "a.b.c", "1.2.3.4.5", "7.2.2593000", "7.-2.2593000.x", "+7.2.2593000.x"]) {
  test(`rejects malformed token ${JSON.stringify(token)}`, () => {
    assert.equal(isValidSessionToken(token, SECRET, 1000), false);
  });
}

test("rejects any token when the secret is empty", () => {
  assert.equal(isValidSessionToken(VECTOR, "", 1000), false);
});

test("/login stays reachable in the dev bypass, even with a cookie", () => {
  assert.equal(hasSessionToRedirect(undefined, undefined, 1000), false);
  assert.equal(hasSessionToRedirect(VECTOR, "", 1000), false);
});

test("/login redirects away only for a valid token", () => {
  assert.equal(hasSessionToRedirect(VECTOR, SECRET, 1000), true);
  assert.equal(hasSessionToRedirect("garbage", SECRET, 1000), false);
  assert.equal(hasSessionToRedirect(undefined, SECRET, 1000), false);
});
